INSERT INTO `question_bank` VALUES (1,'L1: Remember','CO1','Easy',5,'Define primary key, foreign key, and unique key constraints with relational schema examples.','Database Management Systems','Short Answer'),(2,'L2: Understand','CO1','Medium',5,'Explain the ACID properties of transactions and illustrate how write-ahead logging ensures durability.','Database Management Systems','Short Answer'),(3,'L3: Apply','CO2','Medium',8,'Write SQL queries using GROUP BY, HAVING, and INNER JOIN to find employees earning more than the department average.','Database Management Systems','Short Answer'),(4,'L4: Analyze','CO3','Hard',12,'Given an unnormalized relation R(A,B,C,D,E) with functional dependencies, analyze dependencies and decompose into BCNF.','Database Management Systems','Essay'),(5,'L6: Create','CO5','Hard',15,'Design and draw a complete Entity-Relationship (ER) diagram for a Hospital Management System with cardinalities.','Database Management Systems','Essay'),(6,'L2: Understand','CO1','Easy',5,'What is the time complexity of QuickSort in the worst-case scenario and how does Randomized QuickSort mitigate it?','Data Structures & Algorithms','Short Answer'),(7,'L3: Apply','CO2','Medium',10,'Implement an algorithm in Java/C++ to detect a cycle in a directed graph using Depth First Search (DFS).','Data Structures & Algorithms','Short Answer'),(8,'L4: Analyze','CO3','Hard',12,'Compare and contrast Dijkstra algorithm and Bellman-Ford algorithm for single-source shortest paths in weighted graphs.','Data Structures & Algorithms','Essay'),(9,'L5: Evaluate','CO4','Hard',10,'Evaluate the performance trade-offs between AVL Trees and Red-Black Trees in terms of lookup and memory overhead.','Data Structures & Algorithms','Essay'),(10,'L6: Create','CO5','Hard',15,'Design a LRU (Least Recently Used) Cache data structure supporting get and put operations in O(1) time complexity.','Data Structures & Algorithms','Essay'),(11,'L2: Understand','CO1','Easy',5,'Explain the difference between process and thread with state transition diagrams and PCB contents.','Operating Systems','Short Answer'),(12,'L3: Apply','CO2','Medium',10,'Calculate average waiting time and turnaround time for processes using Round Robin and Shortest Job First (SJF).','Operating Systems','Short Answer'),(13,'L4: Analyze','CO3','Hard',12,'Analyze the four necessary conditions for Deadlock and apply Banker algorithm to determine if the system is in safe state.','Operating Systems','Essay'),(14,'L6: Create','CO5','Hard',15,'Design a multi-threaded reader-writer synchronization solution using mutex semaphores to prevent writer starvation.','Operating Systems','Essay'),(15,'L2: Understand','CO1','Easy',5,'Describe the 7 layers of the OSI model and their corresponding protocols in TCP/IP suite.','Computer Networks','Short Answer'),(16,'L3: Apply','CO2','Medium',8,'Apply subnet masking on IP address 192.168.10.0/24 to create 4 subnets with valid host ranges.','Computer Networks','Short Answer'),(17,'L4: Analyze','CO3','Hard',12,'Compare Distance Vector routing with Link State routing protocol regarding convergence time and routing loops.','Computer Networks','Essay');
/*!40000 ALTER TABLE `question_bank` ENABLE KEYS */;
